// --- controls-input.js ---
/* Speed label: "1×" at the top of the range, "0.9×" below it. */
function fmtRate(r) {
  return (Math.round(r * 10) / 10) + "×";
}

volumeEl.addEventListener("input", () => {
  state.volume = Number(volumeEl.value) / 100;
  audio.volume = state.volume;
  volumeOut.textContent = volumeEl.value + "%";
  store.set(LS.volume, volumeEl.value);
});

rateEl.addEventListener("input", () => {
  state.rate = Number(rateEl.value);
  audio.playbackRate = state.rate;
  rateOut.textContent = fmtRate(state.rate);
  store.set(LS.rate, rateEl.value);
});

/* --- progress display mode -------------------------------------------- */
function setProgressMode(mode) {
  if (mode !== "word" || HAS_WORD_TIMES) state.progress = mode;
  progressEl.value = state.progress;
  document.documentElement.dataset.progress = state.progress;
  store.set(LS.progress, state.progress);
  if (state.progress !== "word") clearWord();
}

progressEl.addEventListener("change", () => setProgressMode(progressEl.value));
;

// --- translations.js ---
const englishToggle = document.getElementById("toggleEn");
const ukrainianToggle = document.getElementById("toggleUa");

function setChip(chip, box, open) {
  box.hidden = !open;
  chip.textContent = (box.classList.contains("en") ? "EN " : "UA ") + (open ? "▴" : "▾");
  chip.setAttribute("aria-expanded", String(open));
}

function setEn(i, open) { setChip(els[i].enChip, els[i].enBox, open); }
function setUa(i, open) { setChip(els[i].uaChip, els[i].uaBox, open); }

function setAll(kind, open) {
  const english = kind === "en";
  state[english ? "enOpen" : "uaOpen"] = open;
  els.forEach((entry, i) => (english ? setEn(i, open) : setUa(i, open)));
  const button = english ? englishToggle : ukrainianToggle;
  button.textContent = (open ? "Hide all " : "Reveal all ") + kind.toUpperCase();
  button.setAttribute("aria-pressed", String(open));
  button.classList.toggle("is-on", open);
}

if (englishToggle) englishToggle.addEventListener("click", () => setAll("en", !state.enOpen));
ukrainianToggle.addEventListener("click", () => setAll("ua", !state.uaOpen));
;

// --- controls-common.js ---
/** First section that actually has a timestamp. */
function firstTimed() {
  for (let i = 0; i < CHAPTER.length; i++) if (startOf(i) != null) return i;
  return -1;
}

/**
 * Where should Continuous play begin?
 *   1. the card the user selected (playSection keeps this in sync with the
 *      section playing, so "keep going from here" still works)
 *   2. the section playing right now
 *   3. the last section that was played (remembered across reloads)
 *   4. the first timed section
 */
function resumeIndex() {
  if (state.selected != null && startOf(state.selected) != null) return state.selected;
  if (state.playing && state.index != null) return state.index;
  if (state.lastIndex != null && startOf(state.lastIndex) != null) return state.lastIndex;
  return firstTimed();
}

function updateContinuousButton() {
  const on = state.continuous;
  const from = on ? null : resumeIndex();
  const label = on
    ? "⏹ Stop continuous"
    : (from > 0 ? `▶ Continuous from #${from + 1}` : "▶ Continuous play");
  continuousEl.textContent = label;
  continuousEl.title = on
    ? "Stop continuous playback"
    : (from > 0
        ? `Starts at section ${from + 1} — click another card to change the starting point`
        : "Play the chapter continuously from here");
  continuousEl.setAttribute("aria-pressed", String(on));
  continuousEl.classList.toggle("is-on", on);
}

continuousEl.addEventListener("click", () => {
  if (state.continuous) {
    state.continuous = false;
    stop();
    return;
  }
  const from = resumeIndex();
  if (from < 0) return;
  state.continuous = true;
  updateContinuousButton();
  playSection(from);
  scrollToCard(from);
});

/* --- theme ------------------------------------------------------------ */
function applyTheme(theme) {
  document.documentElement.dataset.theme = theme;
  themeEl.textContent = theme === "dark" ? "☀️" : "🌙";
  themeEl.setAttribute("aria-label", theme === "dark" ? "Switch to light mode" : "Switch to dark mode");
  store.set(LS.theme, theme);
}
themeEl.addEventListener("click", () => {
  applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
});

/* --- header collapse -------------------------------------------------- */
const topbarEl = document.querySelector("header.topbar");
const collapseEl = document.getElementById("collapse");

/* The anchor offset (--hdr) follows the header height, so it is re-measured
   whenever the header collapses or expands. */
const setHdr = () => document.documentElement.style.setProperty("--hdr", topbarEl.offsetHeight + "px");

function applyCollapsed(collapsed) {
  topbarEl.classList.toggle("is-collapsed", collapsed);
  collapseEl.setAttribute("aria-expanded", String(!collapsed));
  const label = collapsed ? "Expand header" : "Collapse header";
  collapseEl.setAttribute("aria-label", label);
  collapseEl.title = label;
  collapseEl.textContent = collapsed ? "▼" : "▲";
  store.set(LS.collapsed, collapsed ? "1" : "0");
  setHdr();
}
collapseEl.addEventListener("click", () => {
  applyCollapsed(!topbarEl.classList.contains("is-collapsed"));
});

/* --- audio state ------------------------------------------------------ */
function showBanner() { banner.hidden = false; }
loadReaderAudio(audio, AUDIO_URL, showBanner);

audio.addEventListener("error", showBanner);
audio.addEventListener("stalled", () => { if (audio.readyState < 2) showBanner(); });

audio.addEventListener("timeupdate", () => {
  clockEl.textContent = fmt(audio.currentTime) + " / " + fmt(audio.duration);
  // Safety net for background tabs, where requestAnimationFrame is throttled:
  // timeupdate still fires, so section boundaries keep working.
  if (state.playing && state.index != null && audio.currentTime >= state.endAt - 0.03) {
    onSegmentEnd();
  }
});
audio.addEventListener("loadedmetadata", () => {
  clockEl.textContent = fmt(0) + " / " + fmt(audio.duration);
  banner.hidden = true;
  // Some browsers seek before metadata is available; re-sync an active section.
  if (state.playing && state.index != null) audio.currentTime = startOf(state.index);
});
// External pause (media keys, browser UI, OS) resets the card buttons.
// Guard: switching sections calls pause() and play() back-to-back, and the
// queued "pause" event must not cancel the section that just started.
audio.addEventListener("pause", () => {
  if (!audio.paused) return;
  if (state.playing) {
    cancelAnimationFrame(state.raf);
    state.playing = false;
    state.index = null;
    markPlaying();
    if (state.continuous) { state.continuous = false; updateContinuousButton(); }
  }
});
;

// --- keyboard.js ---
let focusIndex = 0;
document.addEventListener("keydown", (ev) => {
  const tag = (ev.target.tagName || "").toLowerCase();
  if (tag === "input" || tag === "select" || tag === "textarea") return;
  if (ev.metaKey || ev.ctrlKey || ev.altKey) return;

  const onButton = !!(ev.target.closest && ev.target.closest("button"));
  if (ev.code === "Space" || (ev.code === "Enter" && !onButton)) {
    ev.preventDefault();
    const i = state.index != null ? state.index : focusIndex;
    if (startOf(i) != null) toggleSection(i);
  } else if (ev.key === "ArrowDown" || ev.key === "j") {
    ev.preventDefault();
    selectCard(Math.min(CHAPTER.length - 1, focusIndex + 1), { scroll: true });
    if (state.playing) playSection(focusIndex);
  } else if (ev.key === "ArrowUp" || ev.key === "k") {
    ev.preventDefault();
    selectCard(Math.max(0, focusIndex - 1), { scroll: true });
    if (state.playing) playSection(focusIndex);
  } else if ((ev.key === "e" || ev.key === "E") && document.getElementById("toggleEn")) {
    setAll("en", !state.enOpen);
  } else if (ev.key === "u" || ev.key === "U" || ev.key === "Escape") {
    setAll("ua", !state.uaOpen);
  } else if (ev.key === "c" || ev.key === "C" || ev.key === "ArrowRight") {
    continuousEl.click();
  } else if (ev.key === "t" || ev.key === "T" || ev.key === "ArrowLeft") {
    themeEl.click();
  }
});
;

// --- boot.js ---
(function boot() {
  // Theme: stored preference, else system.
  const stored = store.get(LS.theme);
  applyTheme(stored || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"));

  // Volume / rate preferences.
  const v = store.get(LS.volume);
  if (v != null) { volumeEl.value = v; volumeOut.textContent = v + "%"; state.volume = Number(v) / 100; }
  // The slider owns the allowed values now: clamp an old stored preference
  // (0.75/1.25 from the previous dropdown) onto the 0.5–1.0, 0.1 grid.
  const rawRate = store.get(LS.rate);
  const r = rawRate == null ? NaN : Number(rawRate);
  if (Number.isFinite(r)) {
    rateEl.value = String(Math.min(1, Math.max(0.5, Math.round(r * 10) / 10)));
    if (rateEl.value !== rawRate) store.set(LS.rate, rateEl.value);
  }
  state.rate = Number(rateEl.value);
  rateOut.textContent = fmtRate(state.rate);
  audio.volume = state.volume;

  render();

  // Progress display mode: shared across chapters, word mode needs timings.
  // Word underline is the default; an explicit stored choice always wins.
  progressCtl.hidden = !HAS_WORD_TIMES;
  document.getElementById("progressHelp").hidden = !HAS_WORD_TIMES;
  const storedProgress = store.get(LS.progress);
  setProgressMode(HAS_WORD_TIMES && storedProgress !== "section" ? "word" : "section");

  // Resume point: last played section, else last selected card (survives reload).
  const asIndex = (raw) => {
    if (raw == null || raw === "") return null;
    const n = Number(raw);
    return Number.isInteger(n) && n >= 0 && n < CHAPTER.length ? n : null;
  };
  const sel = asIndex(store.get(LS.selected));
  const last = asIndex(store.get(LS.last));
  if (sel != null) { state.selected = sel; focusIndex = sel; }
  if (last != null) state.lastIndex = last;

  markPlaying();
  updateContinuousButton();

  // Restore the collapsed/expanded header choice, then measure the sticky
  // header (it wraps taller on narrow screens) for the anchor offset.
  applyCollapsed(store.get(LS.collapsed) === "1");
  setHdr(); addEventListener("resize", setHdr);

  // Deep link (#u-N from a vocabulary page or the index): select and show that card.
  const hit = /^#u-(\d+)$/.exec(location.hash);
  if (hit) selectCard(Number(hit[1]) - 1, { scroll: true });
})();
;
